self:
{ config, lib, pkgs, ... }:

let
  cfg = config.services.github-relay;

  consumerToJSON = name: consumer: {
    inherit name;
    inherit (consumer) repo events action;
  } // lib.optionalAttrs (consumer.branches != []) {
    inherit (consumer) branches;
  } // lib.optionalAttrs (consumer.action == "systemd") {
    inherit (consumer) unit;
  } // lib.optionalAttrs (consumer.action == "http") {
    inherit (consumer) url;
  } // lib.optionalAttrs (consumer.action == "command") {
    inherit (consumer) command;
  };

  configJSON = pkgs.writeText "github-relay-config.json" (builtins.toJSON {
    port = cfg.port;
    webhook_secret_file = cfg.webhookSecretFile;
    consumers = lib.mapAttrsToList consumerToJSON cfg.consumers;
  });

  relayPackage = self.packages.${pkgs.system}.default;
in
{
  options.services.github-relay = {
    enable = lib.mkEnableOption "GitHub webhook relay";

    port = lib.mkOption {
      type = lib.types.port;
      default = 8077;
      description = "Port the relay listens on.";
    };

    webhookSecretFile = lib.mkOption {
      type = lib.types.path;
      description = "Path to file containing the GitHub webhook secret.";
    };

    funnel = {
      enable = lib.mkEnableOption "Tailscale Funnel integration";
    };

    consumers = lib.mkOption {
      type = lib.types.attrsOf (lib.types.submodule {
        options = {
          repo = lib.mkOption {
            type = lib.types.str;
            description = "Repository full name (owner/repo) or '*' for all.";
          };

          events = lib.mkOption {
            type = lib.types.listOf lib.types.str;
            description = "List of GitHub event types to match.";
          };

          branches = lib.mkOption {
            type = lib.types.listOf lib.types.str;
            default = [];
            description = "Branch filter. Empty means all branches.";
          };

          action = lib.mkOption {
            type = lib.types.enum [ "systemd" "http" "command" ];
            description = "Action type for this consumer.";
          };

          unit = lib.mkOption {
            type = lib.types.str;
            default = "";
            description = "Systemd unit to start (for action = 'systemd').";
          };

          url = lib.mkOption {
            type = lib.types.str;
            default = "";
            description = "URL to POST to (for action = 'http').";
          };

          command = lib.mkOption {
            type = lib.types.str;
            default = "";
            description = "Shell command to run (for action = 'command').";
          };
        };
      });
      default = {};
      description = "Webhook consumers.";
    };
  };

  config = lib.mkIf cfg.enable {
    environment.etc."github-relay/config.json".source = configJSON;

    systemd.services.github-relay = {
      description = "GitHub Webhook Relay";
      wantedBy = [ "multi-user.target" ];
      after = [ "network.target" "tailscaled.service" ];

      serviceConfig = {
        ExecStart = "${relayPackage}/bin/github-relay -config /etc/github-relay/config.json";
        Restart = "on-failure";
        RestartSec = 5;

        DynamicUser = true;
        ProtectSystem = "strict";
        ProtectHome = true;
        PrivateTmp = true;
        NoNewPrivileges = true;
        ReadOnlyPaths = [ "/" ];
        ReadWritePaths = [ ];

        # Allow reading the webhook secret
        SupplementaryGroups = [ ];
      };
    };

    services.tailscale.permitCertUid = lib.mkIf cfg.funnel.enable "github-relay";

    systemd.services.github-relay-funnel = lib.mkIf cfg.funnel.enable {
      description = "Tailscale Funnel for github-relay";
      wantedBy = [ "multi-user.target" ];
      after = [ "tailscaled.service" "github-relay.service" ];
      wants = [ "tailscaled.service" ];
      serviceConfig = let
        tailscale = lib.getExe' config.services.tailscale.package "tailscale";
      in {
        Type = "oneshot";
        RemainAfterExit = true;
        ExecStart = "${tailscale} funnel --bg --yes --set-path /hooks/github ${toString cfg.port}";
        ExecStop = "${tailscale} funnel --yes reset";
      };
    };
  };
}

package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/patflynn/github-relay/internal/config"
	"github.com/patflynn/github-relay/internal/dispatch"
	"github.com/patflynn/github-relay/internal/webhook"
)

func main() {
	configPath := flag.String("config", "/etc/github-relay/config.json", "path to config file")
	flag.Parse()

	logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	slog.SetDefault(logger)

	cfg, err := config.Load(*configPath)
	if err != nil {
		slog.Error("failed to load config", "error", err)
		os.Exit(1)
	}

	slog.Info("loaded config", "consumers", len(cfg.Consumers), "port", cfg.Port)

	mux := http.NewServeMux()
	mux.HandleFunc("POST /hooks/github", webhookHandler(cfg))

	server := &http.Server{
		Addr:         fmt.Sprintf(":%d", cfg.Port),
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	// Graceful shutdown
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT)
	defer stop()

	go func() {
		slog.Info("starting server", "addr", server.Addr)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			slog.Error("server error", "error", err)
			os.Exit(1)
		}
	}()

	<-ctx.Done()
	slog.Info("shutting down")

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	if err := server.Shutdown(shutdownCtx); err != nil {
		slog.Error("shutdown error", "error", err)
	}
}

func webhookHandler(cfg *config.Config) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		event := r.Header.Get("X-GitHub-Event")
		if event == "" {
			http.Error(w, "missing X-GitHub-Event header", http.StatusBadRequest)
			return
		}

		delivery := r.Header.Get("X-GitHub-Delivery")

		body, err := io.ReadAll(r.Body)
		if err != nil {
			slog.Error("failed to read body", "error", err)
			http.Error(w, "failed to read body", http.StatusInternalServerError)
			return
		}

		// Validate signature
		signature := r.Header.Get("X-Hub-Signature-256")
		if err := webhook.ValidateSignature(body, signature, cfg.WebhookSecretFile); err != nil {
			slog.Warn("signature validation failed", "error", err, "delivery", delivery)
			http.Error(w, "invalid signature", http.StatusForbidden)
			return
		}

		// Parse payload for matching
		var payload map[string]any
		if err := json.Unmarshal(body, &payload); err != nil {
			slog.Error("failed to parse payload", "error", err, "delivery", delivery)
			http.Error(w, "invalid JSON payload", http.StatusBadRequest)
			return
		}

		repo := config.ExtractRepo(payload)
		branch := config.ExtractBranch(event, payload)

		slog.Info("received webhook",
			"event", event,
			"delivery", delivery,
			"repo", repo,
			"branch", branch,
		)

		// Match consumers
		matched := config.Match(cfg.Consumers, repo, event, branch)
		if len(matched) == 0 {
			slog.Debug("no matching consumers", "event", event, "repo", repo)
			w.WriteHeader(http.StatusOK)
			return
		}

		slog.Info("dispatching to consumers", "count", len(matched))

		// Dispatch to all matching consumers
		for _, consumer := range matched {
			if err := dispatch.Dispatch(r.Context(), consumer, body, event, delivery); err != nil {
				// Log error but return 200 to GitHub to avoid retry storms
				slog.Error("dispatch failed",
					"consumer", consumer.Name,
					"action", consumer.Action,
					"error", err,
				)
			}
		}

		w.WriteHeader(http.StatusOK)
	}
}

